"""Synthetic public-account fixtures and WALs generated by stock SQLite.

No live WeChat processes or real account data are accessed by these tests.
"""
import base64
from compression import zstd
from copy import deepcopy
import importlib.util
import json
from pathlib import Path
import shutil
import sqlite3
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parent


def module(name, filename):
    spec = importlib.util.spec_from_file_location(name, ROOT / filename)
    result = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(result)
    return result


reader = module("reader", "read-wechat-biz-metadata.py")
sync = module("sync", "sync-wechat-public-account.py")
BIZ = "MTIzNDU2Nzg5MA=="
TABLE = "Msg_" + "a" * 32


def fixture():
    db = sqlite3.connect(":memory:")
    db.execute(f"CREATE TABLE {TABLE}(message_content BLOB, create_time INTEGER, local_id INTEGER)")
    items = "".join(f"<item><title>Public {i}</title><url><![CDATA[https://mp.weixin.qq.com/s?__biz={biz}&mid=123&idx={i}&sn={'a' * 32}&key=DO_NOT_PERSIST]]></url><pub_time>1700000000</pub_time></item>" for i, biz in ((1, BIZ), (2, BIZ), (3, "OTg3NjU0MzIxMA==")))
    xml = f"<msg><appmsg><mmreader><category>{items}</category></mmreader></appmsg></msg>"
    db.execute(f"INSERT INTO {TABLE} VALUES(?,?,?)", (zstd.compress(xml.encode()), 1700000060, 1))
    db.execute(f"INSERT INTO {TABLE} VALUES(?,?,?)", (xml, 1700000060, 2))
    db.commit()
    raw = db.serialize()
    db.close()
    return raw


class PublicMetadataTests(unittest.TestCase):
    def test_multi_article_filter_compression_and_credential_stripping(self):
        result = reader.extract(fixture(), BIZ)
        self.assertEqual(result["articleCount"], 2)
        self.assertEqual(result["diagnostics"]["zstdDecoded"], 1)
        self.assertEqual(result["accountTable"], TABLE)
        self.assertNotIn("DO_NOT_PERSIST", json.dumps(result))
        self.assertNotIn("key=", json.dumps(result))
        self.assertTrue(all(x["publishedAt"] for x in result["items"]))

    def test_target_table_and_wrong_account(self):
        self.assertEqual(reader.extract(fixture(), BIZ, TABLE)["articleCount"], 2)
        self.assertEqual(reader.extract(fixture(), "MTAwMDAwMDAwMA==", TABLE)["articleCount"], 0)
        with self.assertRaises(ValueError):
            reader.extract(fixture(), BIZ, "Msg_" + "b" * 32)

    def test_incremental_merge_preserves_records_and_distinguishes_import(self):
        metadata = reader.extract(fixture(), BIZ)
        snap = dict(metadata=metadata, authenticatedPages=1, walCommittedFrames=0, walPagesApplied=0, walTailReason="none")
        first = sync.merge(None, snap, "Synthetic account", None)
        self.assertEqual((first["initialImportCount"], first["newlyDiscoveredCount"]), (2, 0))
        second = sync.merge(first, snap, None, None)
        self.assertEqual(second["newlyDiscoveredCount"], 0)
        newer = deepcopy(snap)
        entry = dict(newer["metadata"]["items"][0], id=BIZ + ":124:1")
        newer["metadata"]["items"].append(entry)
        third = sync.merge(second, newer, None, None)
        self.assertEqual((third["newlyDiscoveredCount"], third["totalStoredArticles"]), (1, 3))
        empty = deepcopy(snap)
        empty["metadata"]["items"] = []
        last = sync.merge(third, empty, None, None)
        self.assertEqual(last["status"], "account_not_in_local_cache")
        self.assertEqual(last["totalStoredArticles"], 3)


class NativeWalTests(unittest.TestCase):
    def test_commits_uncommitted_spill_stale_tail_and_corruption(self):
        with tempfile.TemporaryDirectory(prefix="wechat-synthetic-test-") as temporary:
            root = Path(temporary)
            database = root / "synthetic.db"
            db = sqlite3.connect(database)
            db.execute("PRAGMA page_size=4096")
            db.execute("PRAGMA journal_mode=WAL")
            db.execute("PRAGMA wal_autocheckpoint=0")
            db.execute("PRAGMA cache_size=2")
            db.execute("CREATE TABLE public_fixture(data BLOB)")
            db.execute("INSERT INTO public_fixture VALUES('committed')")
            db.commit()
            wal_path = Path(str(database) + "-wal")
            committed = wal_path.read_bytes()
            count = (len(committed) - 32) // 4120
            db.execute("BEGIN")
            db.executemany("INSERT INTO public_fixture VALUES(?)", [(bytes(8192),)] * 12)
            uncommitted = wal_path.read_bytes()
            self.assertGreater(len(uncommitted), len(committed))
            corrupted = bytearray(committed)
            corrupted[32 + 24 + 100] ^= 1
            stale_frame = bytearray(committed[-4120:])
            stale_frame[8] ^= 1
            fixtures = dict(committed=committed, uncommitted=uncommitted, corrupt=bytes(corrupted), stale=committed + stale_frame)
            path = root / "fixtures.json"
            path.write_text(json.dumps({k: base64.b64encode(v).decode() for k, v in fixtures.items()}), encoding="utf-8")
            try:
                process = subprocess.run([shutil.which("pwsh"), "-NoProfile", "-File", str(ROOT / "test-wechat-wal.ps1"), "-FixturesPath", str(path)], capture_output=True, timeout=30, encoding="utf-8", creationflags=subprocess.CREATE_NO_WINDOW)
                self.assertEqual(process.returncode, 0, process.stderr)
                result = json.loads(process.stdout)
                self.assertEqual(result["committed"]["validFrames"], count)
                self.assertEqual(result["committed"]["committedFrames"], count)
                self.assertEqual(result["uncommitted"]["committedFrames"], count)
                self.assertGreater(result["uncommitted"]["validFrames"], count)
                self.assertTrue(result["corrupt"]["rejected"])
                self.assertEqual(result["stale"]["committedFrames"], count)
                self.assertEqual(result["stale"]["tailReason"], "salt-mismatch-stale-tail")
            finally:
                db.rollback()
                db.close()


if __name__ == "__main__":
    unittest.main(verbosity=2)
